```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, m;
    cin >> n;
    vector<int> first(n);
    for (int i = 0; i < n; i++) {
        cin >> first[i];
    }

    cin >> m;
    vector<int> second(m);
    for (int i = 0; i < m; i++) {
        cin >> second[i];
    }

    // Create DP table for LCS
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));

    // Fill DP table using LCS algorithm
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (first[i - 1] == second[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }

    // The answer is the LCS length for the full sequences
    cout << dp[n][m];

    return 0;
}
```

